 "helm": {
  "overview": "Helm is the package manager for Kubernetes that installs and manages applications as versioned charts. It is for platform and application teams who deploy Kubernetes workloads from reusable packages.",
  "shots": [],
  "when": "- You need to install a packaged application (a chart) onto a Kubernetes cluster with one command.\n- You want to upgrade or roll back an installed application to an earlier revision.\n- You need to customize a packaged app's configuration with values files or `--set` overrides.\n- You want to find ready-made charts on Artifact Hub or in a chart repository.",
  "how": "- A chart is a package of Kubernetes resources; `helm create` builds one and `helm package` prepares it for distribution.\n- A release is one installed instance of a chart; each install, upgrade, or rollback increments its revision number.\n- Repositories supply charts; manage them with `helm repo add`, `list`, `update`, and `remove`. Helm 3 and later ship with no default repository.\n- Values configure a chart: defaults come from the chart (`helm show values`), overridden by `-f` files or `--set`, with `--set` taking precedence.\n- Core commands: `helm install`, `helm upgrade`, `helm rollback`, `helm list`, `helm history`, `helm status`, `helm uninstall`.",
  "notFor": "- Ad-hoc inspection or editing of single resources; use kubectl or k9s.\n- Provisioning clusters or cloud infrastructure; use Terraform or OpenTofu.\n- Plain configuration of hosts; use Ansible.",
  "commands": [
   {
    "method": "Arch package (extra)",
    "command": "sudo pacman -S helm",
    "root": "yes",
    "source": ""
   }
  ],
  "commandsStatus": "Verified against an official source (install section above)."
 },
