 "gamemode": {
  "overview": "Feral GameMode is a daemon and library that lets games request temporary CPU and GPU performance optimisations on Linux. It is for Linux gamers who want a performance boost while playing.",
  "shots": [],
  "when": "- A game stutters or runs below its target frame rate and you want the system to favor it while it runs.\n- You launch games from a terminal or a launcher that lacks built-in GameMode support.\n- You want to apply the same performance settings to several games through one config file.\n- You want to check which optimizations are active for a running game.",
  "how": "- GameMode is a daemon (gamemoded) plus a client library that lets a game request temporary system optimizations.\n- You request it by prefixing a command with gamemoderun, for example gamemoderun followed by the game binary.\n- In Steam, set the launch options to gamemoderun %command%.\n- Launchers with built-in support turn it on automatically.\n- Settings live in gamemode.ini; the file is read from system and user locations, and GPU settings are only honored from the system-level /etc file.",
  "notFor": "- Frame-rate overlays or measurements; use MangoHud.\n- Making a non-game program faster in general; GameMode is aimed at games.",
  "commands": [
   {
    "method": "Arch packages (lib32 needs [multilib])",
    "command": "sudo pacman -S gamemode lib32-gamemode",
    "root": "yes",
    "source": ""
   },
   {
    "method": "Join the gamemode group",
    "command": "sudo usermod -aG gamemode $USER",
    "root": "yes",
    "source": ""
   }
  ],
  "commandsStatus": "Verified against an official source (install section above)."
 },
 "mangohud": {
  "overview": "MangoHud is a Vulkan and OpenGL overlay for Linux that displays FPS, frame timings, CPU and GPU statistics during games. It is for Linux gamers and benchmarkers who want performance data on screen.",
  "shots": [
   {
    "url": "screenshots/mangohud-shot-1.gif",
    "caption": ""
   }
  ],
  "when": "- You want to see FPS, frame time and CPU or GPU load while a game runs.\n- You are checking whether a game is hitting temperature, power or VRAM limits.\n- You are testing whether a change such as a GameMode or driver setting actually helps.\n- You want a per-game overlay that you can configure separately for each title.",
  "how": "- MangoHud is a Vulkan and OpenGL overlay that draws live metrics on top of a running game.\n- It is enabled by running the game through mangohud, for example mangohud followed by the program.\n- In Steam, add mangohud %command% to the launch options; in Lutris, add mangohud to the command prefix.\n- Metrics include FPS (on by default), frame time, CPU and GPU load, temperatures, power, memory and clocks.\n- Settings come from a config file: a per-app file in ~/.config/MangoHud/ overrides the global one, and MANGOHUD_CONFIG can set options inline.",
  "notFor": "- Changing system performance settings; use GameMode.\n- Capturing video of gameplay; use OBS Studio.",
  "commands": [
   {
    "method": "Arch packages (lib32 needs [multilib])",
    "command": "sudo pacman -S mangohud lib32-mangohud",
    "root": "yes",
    "source": ""
   }
  ],
  "commandsStatus": "Verified against an official source (install section above)."
 },
