 "nix": {
  "overview": "",
  "shots": [],
  "when": "- You want reproducible, isolated builds and installs of packages on Linux, macOS or WSL.\n- You want several users on one machine to share a single package store (multi-user daemon install).\n- You want to pin or roll back a set of tools so a project builds the same way on every machine.\n- You are a developer or sysadmin who wants declarative environments (Nixpkgs, or NixOS as a full distro).",
  "how": "- A purely functional package manager: each package lives under `/nix/store` at a path derived from its inputs.\n- The recommended Linux install is the multi-user daemon: `curl ... | sh -s -- --daemon`, which needs systemd and SELinux disabled.\n- The single-user install (`--no-daemon`) runs under your own account and creates `/nix` with sudo if needed.\n- Packages come from Nixpkgs; NixOS is a Linux distribution configured from Nix files.",
  "notFor": "- Quick one-off installs where you do not want a new package model or a `/nix` directory.\n- Systems where you cannot run systemd or disable SELinux, unless you use the single-user install.",
  "commands": [
   {
    "method": "multi-user install (recommended)",
    "command": "curl --proto '=https' --tlsv1.2 -L https://nixos.org/nix/install | sh -s -- --daemon",
    "root": "yes",
    "source": "https://nixos.org/download/"
   },
   {
    "method": "single-user install",
    "command": "curl --proto '=https' --tlsv1.2 -L https://nixos.org/nix/install | sh -s -- --no-daemon",
    "root": "no",
    "source": "https://nixos.org/download/"
   }
  ],
  "commandsStatus": "Partly found: Install commands found on the official download page; it has no screenshots and states no minimum RAM."
 },
